import Foundation

/// A versioned build artifact for a Whop React Native App, submitted for review and deployment to a specific platform.
public struct AppBuildListItem: Codable, Hashable, Sendable {
    /// A SHA-256 hash of the uploaded build file, generated by the client and used to verify file integrity.
    public let checksum: String
    /// The datetime the app build was created.
    public let createdAt: Date
    /// A URL to download the app build as a .zip archive.
    public let fileUrl: String
    /// The unique identifier for the app build.
    public let id: String
    /// Whether this build is the currently active production build for its platform.
    public let isProduction: Bool
    /// The target platform for this build.
    public let platform: AppBuildPlatforms
    /// Feedback from the reviewer explaining why the build was rejected. Null if the build has not been reviewed or was approved.
    public let reviewMessage: Nullable<String>
    /// A URL to download the compressed source code archive that produced this build. Null if the build was uploaded without a source archive.
    public let sourceUrl: Nullable<String>
    /// The current review status of this build.
    public let status: AppBuildStatuses
    /// The list of view types this build supports, as declared by the developer.
    public let supportedAppViewTypes: [AppViewTypes]
    /// Additional properties that are not explicitly defined in the schema
    public let additionalProperties: [String: JSONValue]

    public init(
        checksum: String,
        createdAt: Date,
        fileUrl: String,
        id: String,
        isProduction: Bool,
        platform: AppBuildPlatforms,
        reviewMessage: Nullable<String>,
        sourceUrl: Nullable<String>,
        status: AppBuildStatuses,
        supportedAppViewTypes: [AppViewTypes],
        additionalProperties: [String: JSONValue] = .init()
    ) {
        self.checksum = checksum
        self.createdAt = createdAt
        self.fileUrl = fileUrl
        self.id = id
        self.isProduction = isProduction
        self.platform = platform
        self.reviewMessage = reviewMessage
        self.sourceUrl = sourceUrl
        self.status = status
        self.supportedAppViewTypes = supportedAppViewTypes
        self.additionalProperties = additionalProperties
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.checksum = try container.decode(String.self, forKey: .checksum)
        self.createdAt = try container.decode(Date.self, forKey: .createdAt)
        self.fileUrl = try container.decode(String.self, forKey: .fileUrl)
        self.id = try container.decode(String.self, forKey: .id)
        self.isProduction = try container.decode(Bool.self, forKey: .isProduction)
        self.platform = try container.decode(AppBuildPlatforms.self, forKey: .platform)
        self.reviewMessage = try container.decode(Nullable<String>.self, forKey: .reviewMessage)
        self.sourceUrl = try container.decode(Nullable<String>.self, forKey: .sourceUrl)
        self.status = try container.decode(AppBuildStatuses.self, forKey: .status)
        self.supportedAppViewTypes = try container.decode([AppViewTypes].self, forKey: .supportedAppViewTypes)
        self.additionalProperties = try decoder.decodeAdditionalProperties(using: CodingKeys.self)
    }

    public func encode(to encoder: Encoder) throws -> Void {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try encoder.encodeAdditionalProperties(self.additionalProperties)
        try container.encode(self.checksum, forKey: .checksum)
        try container.encode(self.createdAt, forKey: .createdAt)
        try container.encode(self.fileUrl, forKey: .fileUrl)
        try container.encode(self.id, forKey: .id)
        try container.encode(self.isProduction, forKey: .isProduction)
        try container.encode(self.platform, forKey: .platform)
        try container.encode(self.reviewMessage, forKey: .reviewMessage)
        try container.encode(self.sourceUrl, forKey: .sourceUrl)
        try container.encode(self.status, forKey: .status)
        try container.encode(self.supportedAppViewTypes, forKey: .supportedAppViewTypes)
    }

    /// Keys for encoding/decoding struct properties.
    enum CodingKeys: String, CodingKey, CaseIterable {
        case checksum
        case createdAt = "created_at"
        case fileUrl = "file_url"
        case id
        case isProduction = "is_production"
        case platform
        case reviewMessage = "review_message"
        case sourceUrl = "source_url"
        case status
        case supportedAppViewTypes = "supported_app_view_types"
    }
}